try {
  const body = $input.first().json.body || $input.first().json;
  // VAPI wraps payload under message; some direct calls are flat
  const msg = body.message || body;

  const callData = msg.call || {};
  const artifact = msg.artifact || {};
  const analysis = msg.analysis || {};

  // Extract caller number from multiple possible fields
  const callerNumber = (
    callData.customer?.number ||
    callData.phoneNumber?.number ||
    body.phoneNumber ||
    body.caller_number ||
    ''
  ).trim();

  // Extract VAPI call ID
  const vapiCallId = (callData.id || body.call_id || '').trim() || null;

  // Calculate duration from timestamps or use provided value
  let duration = 0;
  if (callData.startedAt && callData.endedAt) {
    duration = Math.round((new Date(callData.endedAt) - new Date(callData.startedAt)) / 1000);
  } else if (callData.duration) {
    duration = parseInt(callData.duration);
  } else if (body.durationSeconds) {
    duration = parseInt(body.durationSeconds);
  }

  const transcript = artifact.transcript || body.transcript || '';
  const summary = analysis.summary || body.summary || '';
  const recordingUrl = (artifact.recordingUrl || body.recording_url || '').trim() || null;
  const cost = parseFloat(callData.cost || body.cost || 0) || null;
  const callStatus = msg.endedReason === 'assistant-error' ? 'failed' : 'completed';

  // Intent classification from transcript + summary
  const text = (transcript + ' ' + summary).toLowerCase();
  let intent = 'diger';
  if (text.includes('randevu') && (text.includes('aldım') || text.includes('oluştur') || text.includes('alındı') || text.includes('almak'))) {
    intent = 'randevu_alma';
  } else if (text.includes('iptal') || text.includes('iptal ettim')) {
    intent = 'randevu_iptal';
  } else if (text.includes('ertele') || text.includes('taşı') || text.includes('değiştir')) {
    intent = 'randevu_alma';
  } else if (text.includes('geri ara') || text.includes('geri arama')) {
    intent = 'geri_arama';
  } else if (text.includes('bilgi') || text.includes('saat') || text.includes('doktor') || text.includes('uzman')) {
    intent = 'bilgi';
  }

  // Use analysis.structuredData.intent if provided by VAPI
  if (analysis.structuredData?.intent) {
    intent = analysis.structuredData.intent;
  }

  return [{ json: { vapiCallId, callerNumber, duration, transcript, summary, intent, callStatus, recordingUrl, cost, error: false } }];
} catch(e) {
  return [{ json: { error: true, message: String(e) } }];
}
